
import React, { useEffect, useState } from "react";
import axios from "axios";

const API_KEY = "dict.1.1.20261021T164112Z.371eb9542093179e.ff7ec2e6b8a8978901de79b49578c1d0906ecd4b";

const doTranslation = async (input) => {
  if (!input.trim()) return "";

  const base = "https://dictionary.yandex.net/api/v1/dicservice.json";

  const url =
    `${base}/lookup?key=${API_KEY}` +
    `&lang=ru-en&text=${encodeURIComponent(input)}`;

  try {
    const { data } = await axios.get(url);
    return data.def?.[0]?.tr?.[0]?.text || "";
  } catch (error) {
    console.error("Ошибка перевода:", error);
    return "";
  }
};

export default function Translate({ text }) {
  const [translated, setTranslated] = useState("");

  useEffect(() => {
    let active = true;

    setTranslated("");

    doTranslation(text).then((result) => {
      if (active) {
        setTranslated(result);
      }
    });

    return () => {
      active = false;
    };
  }, [text]);

  return <h1>{translated}</h1>;
}
